-- United States milestones (Stage 4 deep-dive/tracker migration)
-- 6 total: 4 deep-dive-only + 2 tracker-matched (us-federal-b2g, us-dbnalliance).
-- Milestone count (6) exceeds the static page's rcard count (5) because us-federal-b2g
-- is kept genuinely separate from the deep-dive's 2015 OMB-memo rcard -- the 2015 date
-- is when the directive was issued, while the tracker's 2018-12-01 date is the
-- "in force since" effective date explicitly named in the tracker's own system text,
-- a different point in the same policy's lifecycle, per the Denmark non-overlapping
-- milestone precedent (tracker entries can lack a 1:1 rcard match).

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'us-omb-2015', id, '2015-07-01', 0, NULL FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('us-omb-2015', 'en', 'OMB Memorandum M-15-19 directs federal agencies to e-invoicing', 'Federal agencies are directed to move to electronic invoicing for appropriate procurements by the end of fiscal year 2018, using a federal shared service provider or an approved solution such as the Treasury''s Invoice Processing Platform.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'us-federal-b2g', id, '2018-12-01', 1, 'https://www.ipp.gov' FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('us-federal-b2g', 'en', 'Federal agencies required to manage invoices electronically (B2G, in force since 2018)', 'The Office of Management and Budget directed federal agencies to move to electronic invoicing for appropriate procurements. Most now use the Treasury''s Invoice Processing Platform (IPP) — but there is no single mandated format, and no domestic B2B mandate of any kind.', '["If you sell to federal agencies, confirm you''re set up on the IPP or your agency''s designated e-invoicing channel", "Retain electronic invoice records so they remain accessible, accurate, and legible per IRS guidance (Publication 583)"]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'us-bpc-pilot-2022', id, '2022-04-01', 0, NULL FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('us-bpc-pilot-2022', 'en', 'Business Payments Coalition E-invoice Exchange Market Pilot begins', 'The first wave connects around 20 businesses; by May 2022 over 75 international businesses have joined across three rollout waves, testing secure e-invoice delivery between service providers.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'us-pilot-finalised-2023', id, '2023-01-01', 0, NULL FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('us-pilot-finalised-2023', 'en', 'Pilot extends; rules and specifications finalised', 'The BPC and Federal Reserve formalise the exchange framework''s rules and technical specifications, moving from proof-of-concept toward a durable governance structure.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'us-dbnalliance', id, '2024-01-01', 1, 'https://dbnalliance.org' FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('us-dbnalliance', 'en', 'DBNAlliance B2B e-invoice exchange network live (voluntary, market-led)', 'The Digital Business Networks Alliance (DBNAlliance) — a nonprofit that grew out of a Federal Reserve / Business Payments Coalition pilot — now operates a Peppol-style four-corner network for voluntary structured B2B e-invoice exchange across the US and Canada. No federal or state law requires adoption.', '["Consider connecting via a DBNAlliance-certified service provider ahead of any future mandate", "If trading with partners in countries that already mandate e-invoicing (EU, Mexico, Brazil, etc.), ensure your systems can still produce their required formats"]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'us-first-invoice-2024', id, '2024-03-01', 0, NULL FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('us-first-invoice-2024', 'en', 'First invoice successfully transferred via the DBNAlliance network', 'A genuine operational milestone — proof the network functions in production, not just in pilot testing.', '[]');
